actions.script:
const L = (text) => ec.l10n.localize(text)
defaults = {}
balanceList = []
balancingError = ''
if (!isEdge) return
let out = {}
// a probe (Practices-App-Dev §4): a failure is shown on the page rather than failing it
ec.message.pushErrors()
try {
    out = ec.service.sync().name('org.moqui.edge.EdgeServices.get#EdgeBalancing').call() || {}
    if (ec.message.hasError()) balancingError = ec.message.getErrorsString()
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}
if (balancingError) return
defaults = {stickyCookie: out.stickyCookie || '',
    setAsideText: ec.resource.expand('After ${failures} failures in a row, for ${seconds} s', '',
        {failures: out.setAsideFailures ?? '', seconds: out.setAsideSeconds ?? ''})}
const states = {live: L('Live'), starting: L('Starting'), draining: L('Draining'), stopping: L('Stopping')}
balanceList = Array.from(out.memberList || []).map((member) => {
    const [workLabel, workColor] = member.takesWork ? [L('Taking work'), 'positive']
        : member.setAside ? [L('Set aside'), 'warning']
        : !member.linked ? [L('Not linked'), 'grey'] : [states[member.state] || member.state || '', 'info']
    return {pairedNodeId: member.pairedNodeId, instanceId: member.instanceId, workLabel, workColor,
        inFlightText: String(member.inFlight ?? 0), requestsText: String(member.requests ?? 0),
        failuresText: String(member.failuresInRow ?? 0), setAsidesText: String(member.setAsides ?? 0),
        untilText: member.setAsideUntil ? ec.l10n.format(member.setAsideUntil, '') : ''}
})
